<script setup>
import { ref, nextTick } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import { ArrowRightIcon, MagnifyingGlassIcon, MapPinIcon } from '@heroicons/vue/24/outline';
import LaunchUpdates from './LaunchUpdates.vue';
import AppNotice from '@/Components/Product/AppNotice.vue';
const props = defineProps({ editorial: Object, audiences: Array, filters: Object });
const selected = ref('');
const city = ref(props.filters?.location || '');
const explored = ref(false);
const allServices = ref(false);
const asset = name => `/images/marketing/industries/${name}.webp`;
function explore() {
    if (selected.value) return router.get(`/marketplace/explore/${selected.value}`, city.value ? {city:city.value} : {});
    explored.value = true;
    nextTick(() => document.getElementById('launch-services')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));
}
const categoryFor = query => props.editorial.categories.find(category => category.audiences.includes(query))?.slug;
</script>
