            <label><MapPinIcon aria-hidden="true"/><span><small>Your city</small><input v-model="city" maxlength="150" placeholder="Where would you like to book?" aria-label="Your city" autocomplete="address-level2"></span></label>
            <button class="launch-button">Explore <ArrowRightIcon aria-hidden="true"/></button>
        </form>
    </section>
    <p class="launch-strip">We’re welcoming businesses to Marketplace. Explore services and get updates for your area.</p>
    <div class="launch-width launch-content">
        <section id="launch-services" class="launch-section" aria-labelledby="launch-services-title">
            <div class="launch-heading"><h2 id="launch-services-title">What would feel good today?</h2><button type="button" class="launch-text-link" :aria-expanded="allServices" aria-controls="all-launch-services" @click="allServices=!allServices">{{allServices ? 'Show less' : 'Explore all services'}}<ArrowRightIcon aria-hidden="true"/></button></div>
            <AppNotice v-if="explored || filters?.q || filters?.location || filters?.nearby" title="Your next favourite is still on its way" :description="city ? `We’re still welcoming businesses in ${city}. Explore the guides below or get an email when businesses join your area.` : 'We’re still welcoming businesses. Explore the guides below or get updates for your area.'"><template #actions><a href="#area-updates" class="launch-text-link">Get updates for my area<ArrowRightIcon aria-hidden="true"/></a></template></AppNotice>
            <div class="launch-categories"><Link v-for="category in editorial.categories" :key="category.slug" :href="`/marketplace/explore/${category.slug}`" class="launch-category"><img :src="asset(category.image)" alt="" width="320" height="390" loading="lazy"><span>{{category.name}}<ArrowRightIcon aria-hidden="true"/></span></Link></div>
            <div v-if="allServices" id="all-launch-services" class="all-launch-services"><p>Explore all the kinds of businesses you can find on Clipperdesk as they join.</p><div><Link v-for="audience in audiences" :key="audience.query" :href="`/marketplace/explore/${categoryFor(audience.query)}`">{{audience.name}}<ArrowRightIcon aria-hidden="true"/></Link></div></div>
        </section>
        <section class="launch-section" aria-labelledby="launch-guides-title"><div class="launch-heading"><h2 id="launch-guides-title">A little <em>know-how</em> before you go.</h2><Link class="launch-text-link" href="/marketplace/guides">All guides<ArrowRightIcon aria-hidden="true"/></Link></div><div class="launch-guides"><article v-for="guide in editorial.guides" :key="guide.slug"><Link :href="`/marketplace/guides/${guide.slug}`" class="guide-photo" tabindex="-1" aria-hidden="true"><img :src="asset(guide.image)" alt="" width="480" height="260" loading="lazy"><span>GUIDE</span></Link><h3><Link :href="`/marketplace/guides/${guide.slug}`">{{guide.title}}</Link></h3><p>{{guide.description}}</p><Link :href="`/marketplace/guides/${guide.slug}`" class="launch-text-link" :aria-label="`Read ${guide.title}`">Read guide<ArrowRightIcon aria-hidden="true"/></Link></article></div></section>
        <LaunchUpdates :city="city" />
        <section class="launch-business"><div><h2>Be someone’s <em>next favourite.</em></h2><p>Bring your business to Clipperdesk. Manage your day and welcome your next customer.</p></div><div class="launch-business-actions"><a href="/" class="launch-button lime">Explore Clipperdesk Business<ArrowRightIcon aria-hidden="true"/></a><a href="/features/product-walkthrough" class="launch-text-link">See how it works<ArrowRightIcon aria-hidden="true"/></a></div></section>
    </div>
